export const settlementControllerAmend = (
    id: number,
    amendRequest: AmendRequest,
 signal?: AbortSignal
) => {


      return apiMutator<SettlementView>(
      {url: `/api/settlements/${id}`, method: 'PATCH',
      headers: {'Content-Type': 'application/json', },
      data: amendRequest, signal
    },
      );
    }




